package net.officefloor.hq.app.invoices;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import jakarta.persistence.Transient;
import org.hibernate.annotations.Formula;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.MathContext;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.clients.Currency;

/** An invoice raised for a client, made of lines. */
@Entity
@Table(name = "invoice")
public class Invoice {

    /** A due date set by hand can be at most this many days after the issue date. */
    public static final int MAX_DUE_DAYS = 120;

    /** Payments that leave less than this many US dollars' worth still due have the rest written off. */
    public static final BigDecimal WRITE_OFF_LIMIT = new BigDecimal("1.00");

    /** A part payment must be at least this share of the grand total, unless it settles the invoice. */
    public static final BigDecimal MINIMUM_PART_SHARE = new BigDecimal("0.10");

    /** The most retention a draft can hold back, as a percentage of the amount before tax. */
    public static final BigDecimal MAX_RETENTION_PCT = new BigDecimal("20");

    /** Released retention falls due this many days after the day it was released. */
    public static final int RETENTION_DUE_DAYS = 30;

    /** The fewest and most monthly instalments a plan can have. */
    public static final int MIN_INSTALMENTS = 2;
    public static final int MAX_INSTALMENTS = 24;

    /** The highest annual interest rate a plan can charge, as a percentage. */
    public static final BigDecimal MAX_INSTALMENT_RATE = new BigDecimal("30");

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id")
    private Long clientId;

    @Enumerated(EnumType.STRING)
    private InvoiceStatus status;

    @Column(name = "issue_date")
    private LocalDate issueDate;

    @Column(name = "due_date")
    private LocalDate dueDate;

    @Column(name = "manual_due_date")
    private boolean manualDueDate;

    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    @Column(name = "discount_amount")
    private BigDecimal discountAmount = BigDecimal.ZERO;

    @Column(name = "discount_cap")
    private BigDecimal discountCap;

    @Column(name = "discount_reason")
    private String discountReason;

    @Column(name = "retention_pct")
    private BigDecimal retentionPct = BigDecimal.ZERO;

    @Column(name = "retention_released_on")
    private LocalDate retentionReleasedOn;

    /** How many monthly instalments the invoice is spread over; null when it has no plan. */
    @Column(name = "instalments")
    private Integer instalments;

    /** The annual interest rate of the plan, a percentage from 0 to {@link #MAX_INSTALMENT_RATE}. */
    @Column(name = "instalment_rate")
    private BigDecimal instalmentRate = BigDecimal.ZERO;

    /** Whether the invoice's client is tax exempt, so no line is taxed; read from the client. */
    @Formula("(SELECT c.tax_exempt FROM client c WHERE c.id = client_id)")
    private boolean clientTaxExempt;

    /** The id of the invoice this credit note credits; null for an ordinary invoice. */
    @Column(name = "credit_of")
    private Long creditOf;

    /** The code of the currency the invoice's client is billed in; read from the client. */
    @Formula("(SELECT c.currency FROM client c WHERE c.id = client_id)")
    private String clientCurrency;

    /**
     * The US dollars one unit of the client's currency is worth, from the workspace rates; read from
     * them, null when no rate is set (taken at par).
     */
    @Formula("(SELECT s.setting_value FROM app_setting s, client c WHERE c.id = client_id AND s.name = 'usd_per_' || c.currency)")
    private String usdPer;

    /** The client's early-payment discount, a percentage of the grand total; read from the client. */
    @Formula("(SELECT c.early_pay_pct FROM client c WHERE c.id = client_id)")
    private BigDecimal earlyPayPct;

    /** How many days after the issue date the invoice counts as paid off early; read from the client. */
    @Formula("(SELECT c.early_pay_days FROM client c WHERE c.id = client_id)")
    private Integer earlyPayDays;

    /** The early discount the invoice was settled with; 0 when none was taken. */
    @Column(name = "early_discount")
    private BigDecimal earlyDiscount = BigDecimal.ZERO;

    /** An issued credit note's grand total, kept when it is issued; null until then. */
    @Column(name = "credit_total")
    private BigDecimal creditTotal;

    /**
     * What this credit note took off its original when issued (what it owed, then retention it held);
     * null until then. Any rest of its grand total was held on the client's account as credit.
     */
    @Column(name = "credit_applied")
    private BigDecimal creditApplied;

    /** The part of {@link #creditApplied} that cleared retention its original held back. */
    @Column(name = "credit_retention")
    private BigDecimal creditRetention = BigDecimal.ZERO;

    /** What the credit notes issued against this invoice took off it; read from them. */
    @Formula("(SELECT COALESCE(SUM(cn.credit_applied), 0) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
    private BigDecimal credited = BigDecimal.ZERO;

    /** The part of what is credited that cleared retention held back; read from the credit notes. */
    @Formula("(SELECT COALESCE(SUM(cn.credit_retention), 0) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
    private BigDecimal retentionCredited = BigDecimal.ZERO;

    /** How many credit notes have been issued against this invoice; read from them. */
    @Formula("(SELECT COUNT(*) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
    private int creditNotesIssued;

    /**
     * The late interest charged so far (see {@link #accrueLateInterest}); not stored, worked out again
     * each time the invoice is read.
     */
    @Transient
    private BigDecimal lateInterest = BigDecimal.ZERO;

    /**
     * The late fee charged (see {@link #accrueLateInterest}), in the invoice's currency; not stored,
     * worked out again each time the invoice is read.
     */
    @Transient
    private BigDecimal lateFee = BigDecimal.ZERO;

    /**
     * The late interest each instalment of a plan has been charged (see {@link #accrueLateInterest}), in
     * the order of the instalments; empty when none is. Not stored, worked out again each time the
     * invoice is read.
     */
    @Transient
    private List<BigDecimal> instalmentInterest = List.of();

    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true)
    @JoinColumn(name = "invoice_id", nullable = false)
    @OrderBy("id")
    private List<InvoiceLine> lines = new ArrayList<>();

    protected Invoice() {
    }

    /** A new, empty draft for a client, issued and due on the given dates. */
    public static Invoice draft(Long clientId, boolean clientTaxExempt, Currency currency, LocalDate issueDate,
            LocalDate dueDate) {
        Invoice invoice = new Invoice();
        invoice.clientId = clientId;
        invoice.clientTaxExempt = clientTaxExempt;
        invoice.clientCurrency = currency.name();
        invoice.status = InvoiceStatus.DRAFT;
        invoice.issueDate = issueDate;
        invoice.dueDate = dueDate;
        return invoice;
    }

    /**
     * A new draft for the same client with copies of this invoice's lines and the same invoice
     * discount, issued and due on the given dates. Payments stay with this invoice.
     */
    public Invoice duplicate(LocalDate issueDate, LocalDate dueDate) {
        Invoice copy = draft(clientId, clientTaxExempt, currency(), issueDate, dueDate);
        copy.discountPct = discountPct;
        copy.discountAmount = discountAmount;
        copy.discountCap = discountCap;
        copy.discountReason = discountReason;
        copy.retentionPct = retentionPct;
        copy.instalments = instalments;
        copy.instalmentRate = instalmentRate;
        lines.forEach(line -> copy.lines.add(line.copy()));
        return copy;
    }

    /**
     * A new, empty draft credit note for the sent invoice, issued on the given date: same client, no
     * discount, taxed as the original's lines are.
     */
    public Invoice creditNote(LocalDate issueDate) {
        Invoice note = draft(clientId, clientTaxExempt, currency(), issueDate, null);
        note.creditOf = id;
        return note;
    }

    /** The currency the invoice is in: its client's. */
    public Currency currency() {
        return Currency.orUsd(clientCurrency);
    }

    /**
     * How many decimals its amounts have: 2, to the cent, or 0 for whole yen. Wherever an amount is
     * rounded to the cent it is rounded to this instead.
     */
    public int scale() {
        return currency().scale();
    }

    /** Nothing, in the invoice's currency. */
    private BigDecimal zero() {
        return BigDecimal.ZERO.setScale(scale());
    }

    /** Whether what is left is worth less than {@link #WRITE_OFF_LIMIT} US dollars at the workspace rates. */
    private boolean isSmallEnoughToWriteOff(BigDecimal left) {
        BigDecimal rate = usdPer == null ? BigDecimal.ONE : new BigDecimal(usdPer.trim());
        return left.multiply(rate).compareTo(WRITE_OFF_LIMIT) < 0;
    }

    /** Whether this is a credit note against another invoice. */
    public boolean isCreditNote() {
        return creditOf != null;
    }

    /** The id of the invoice this credit note credits; null for an ordinary invoice. */
    public Long getCreditOf() {
        return creditOf;
    }

    /** The number shown: CN-... for a credit note, otherwise INV-... (see {@link InvoiceNumber}). */
    public String number() {
        return isCreditNote() ? InvoiceNumber.creditNoteOf(id) : InvoiceNumber.of(id);
    }

    /** What the credit notes issued against this invoice add up to, to the cent. */
    public BigDecimal getCredited() {
        return (credited == null ? BigDecimal.ZERO : credited).setScale(scale(), RoundingMode.HALF_UP);
    }

    /** Whether a credit note has been issued against this invoice: it can then no longer change. */
    public boolean hasCreditNotesIssued() {
        return creditNotesIssued > 0;
    }

    /**
     * Issues a draft credit note on the given date, keeping its grand total at the tax rate and what
     * its original took of it (the part of that clearing held retention).
     */
    public void markIssued(LocalDate issueDate, BigDecimal taxRate, BigDecimal applied, BigDecimal toRetention) {
        this.creditTotal = total(taxRate);
        this.creditApplied = applied;
        this.creditRetention = toRetention;
        this.status = InvoiceStatus.CREDIT_NOTE;
        this.issueDate = issueDate;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssueDate() {
        return issueDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** The percentage taken off the subtotal, 0 to 100 with up to two decimals. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** The fixed amount taken off the subtotal, to the cent; 0 when the discount is a percentage. */
    public BigDecimal getDiscountAmount() {
        return discountAmount;
    }

    /** The most taken off the invoice in all, line discounts included, to the cent; null when there is no cap. */
    public BigDecimal getDiscountCap() {
        return discountCap;
    }

    /** Why the discount was given; null when no reason was given. */
    public String getDiscountReason() {
        return discountReason;
    }

    /** Sets why the discount was given; blank is no reason. */
    public void setDiscountReason(String discountReason) {
        this.discountReason = discountReason == null || discountReason.isBlank() ? null : discountReason.strip();
    }

    /** Whether the discount takes off more than a fifth of the subtotal, after any cap, and so needs a reason. */
    public boolean discountNeedsReason() {
        return discount().multiply(BigDecimal.valueOf(5)).compareTo(subtotal()) > 0;
    }

    /** Whether the discount needs a reason but has none. */
    public boolean discountLacksReason() {
        return discountNeedsReason() && discountReason == null;
    }

    /** Sets the percentage taken off the subtotal, clearing any fixed amount; it has already been checked. */
    public void setDiscountPct(BigDecimal discountPct) {
        this.discountPct = discountPct;
        this.discountAmount = BigDecimal.ZERO;
    }

    /** Sets the most taken off the invoice in all, or null for no cap; it has already been checked as money. */
    public void setDiscountCap(BigDecimal discountCap) {
        this.discountCap = discountCap;
    }

    /**
     * Sets a fixed amount taken off the subtotal, clearing any percentage; it has already been checked
     * as money. An amount over the subtotal is refused.
     */
    public void setDiscountAmount(BigDecimal discountAmount) {
        if (discountAmount.compareTo(subtotal()) > 0) {
            throw new InvoiceRejectedException("The discount cannot be more than the subtotal of "
                    + currency().format(subtotal()) + ".");
        }
        this.discountAmount = discountAmount;
        this.discountPct = BigDecimal.ZERO;
    }

    /** The percentage of the amount before tax held back as retention, 0 to {@link #MAX_RETENTION_PCT}. */
    public BigDecimal getRetentionPct() {
        return retentionPct;
    }

    /** Sets the percentage held back as retention; it has already been checked. */
    public void setRetentionPct(BigDecimal retentionPct) {
        this.retentionPct = retentionPct;
    }

    /** The day the retention was released; null while it is still held. */
    public LocalDate getRetentionReleasedOn() {
        return retentionReleasedOn;
    }

    /** The day released retention falls due, {@link #RETENTION_DUE_DAYS} after its release; null while held. */
    public LocalDate retentionDueDate() {
        return retentionReleasedOn == null ? null : retentionReleasedOn.plusDays(RETENTION_DUE_DAYS);
    }

    /** Releases the retention on the given day, so it is added to the amount due. */
    public void releaseRetention(LocalDate on) {
        this.retentionReleasedOn = on;
    }

    /**
     * The retention: the retention percentage of the amount before tax (the subtotal less the
     * discount), rounded down to the cent. Tax is never held back, so the tax rate does not change it.
     */
    public BigDecimal retention(BigDecimal taxRate) {
        if (isCreditNote()) {
            return zero();
        }
        return subtotal().subtract(discount()).multiply(retentionPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
    }

    /**
     * The retention still held back at the tax rate: all of it until it is released, less what credit
     * notes have cleared of it; then nothing.
     */
    public BigDecimal retentionHeld(BigDecimal taxRate) {
        if (retentionReleasedOn != null) {
            return zero();
        }
        BigDecimal cleared = retentionCredited == null ? BigDecimal.ZERO : retentionCredited;
        return retention(taxRate).subtract(cleared).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
    }

    /**
     * How a credit note of the amount comes off this invoice once the given amount has been paid, at
     * the tax rate: first what it still owes, then the retention it holds back. The part taken off in
     * all, and of that the part clearing retention; the rest is left over as credit.
     */
    public BigDecimal[] creditTaken(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
        BigDecimal toDue = amount.min(amountDue(paid, taxRate).max(BigDecimal.ZERO));
        BigDecimal toRetention = amount.subtract(toDue).min(retentionHeld(taxRate));
        return new BigDecimal[] { toDue.add(toRetention), toRetention };
    }

    /** The retention released at the tax rate: nothing until it is released, then all of it. */
    public BigDecimal retentionReleased(BigDecimal taxRate) {
        return retentionReleasedOn == null ? zero() : retention(taxRate);
    }

    /**
     * What the invoice is owed in all, held retention left out: the grand total (the plan total when it
     * is spread over instalments) less what is credited and held, plus the late fee and interest charged.
     */
    private BigDecimal payable(BigDecimal taxRate) {
        return payableBeforeInterest(taxRate).add(getLateFee()).add(getLateInterest());
    }

    /** As {@link #payable}, but without the late fee and interest charged. */
    private BigDecimal payableBeforeInterest(BigDecimal taxRate) {
        BigDecimal owed = hasPlan() ? planTotal(taxRate) : total(taxRate);
        return owed.subtract(getCredited()).subtract(retentionHeld(taxRate)).subtract(getEarlyDiscountTaken());
    }

    /** The late interest charged, to the cent; 0 when none is. */
    public BigDecimal getLateInterest() {
        return lateInterest.setScale(scale(), RoundingMode.HALF_UP);
    }

    /** The late fee charged, in the invoice's currency; 0 when none is. */
    public BigDecimal getLateFee() {
        return lateFee.setScale(scale(), RoundingMode.HALF_UP);
    }

    /**
     * The late fee in the invoice's currency: the fee in US dollars converted as a payment in another
     * currency is, through the workspace rate, rounded half up to the currency's step.
     */
    private BigDecimal lateFeeIn(BigDecimal feeUsd) {
        if (currency() == Currency.USD) {
            return feeUsd.setScale(scale(), RoundingMode.HALF_UP);
        }
        BigDecimal rate = usdPer == null ? BigDecimal.ONE : new BigDecimal(usdPer.trim());
        return currency().roundToStep(feeUsd.divide(rate, MathContext.DECIMAL128));
    }

    /**
     * Works out the late fee and late interest charged by the given day, at the late fee (in US
     * dollars) and annual rate (a percentage), from the payments (those not reversed count), and keeps
     * them as part of what is payable. The fee is charged once, on the day the invoice becomes overdue
     * ({@link #GRACE_DAYS} days after its due date), when something is still owed then; it earns no
     * interest, and a payment from then on pays it first. A sent invoice not
     * spread over instalments, with something still owed more than {@link #GRACE_DAYS} days after its
     * due date, earns interest from the end of its grace week ({@link #GRACE_DAYS} days after its due
     * date), compounded daily at rate / 365: a balance B owing for
     * d days earns B x ((1 + rate / 100 / 365)^d - 1), rounded half up to the cent. Each payment after
     * the grace week ends a period; every period earns interest on what the invoice still owed during it
     * (earlier interest, the fee and retention left out), and a payment pays the fee, then the interest
     * earned so far, then the invoice. An invoice spread over instalments instead earns interest
     * instalment by instalment (see {@link #accrueInstalmentInterest}), and no late fee.
     */
    public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
            BigDecimal lateFeeUsd, LocalDate today) {
        this.lateInterest = BigDecimal.ZERO;
        this.lateFee = BigDecimal.ZERO;
        this.instalmentInterest = List.of();
        if (status == InvoiceStatus.SENT && !isCreditNote() && hasPlan()) {
            accrueInstalmentInterest(payments, taxRate, annualRate, today);
            return;
        }
        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || dueDate == null
                || !today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
            return;
        }
        boolean earnsInterest = annualRate != null && annualRate.signum() > 0;
        BigDecimal fee = lateFeeUsd == null || lateFeeUsd.signum() <= 0 ? zero() : lateFeeIn(lateFeeUsd);
        if (!earnsInterest && fee.signum() <= 0) {
            return;
        }
        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
        }
        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
                .filter(p -> !p.on().isAfter(today))
                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(GRACE_DAYS)))
                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
        if (owed.subtract(paidInGrace).signum() <= 0) {
            return;
        }
        BigDecimal daily = earnsInterest
                ? BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128))
                : null;
        LocalDate overdueOn = dueDate.plusDays(GRACE_DAYS + 1);
        BigDecimal charged = BigDecimal.ZERO;
        BigDecimal unpaidInterest = BigDecimal.ZERO;
        BigDecimal unpaidFee = BigDecimal.ZERO;
        boolean feeCharged = false;
        LocalDate from = dueDate.plusDays(GRACE_DAYS);
        for (Part part : inOrder) {
            if (!feeCharged && !part.on().isBefore(overdueOn)) {
                unpaidFee = fee;
                feeCharged = true;
            }
            BigDecimal toFee = part.amount().min(unpaidFee).max(BigDecimal.ZERO);
            unpaidFee = unpaidFee.subtract(toFee);
            BigDecimal rest = part.amount().subtract(toFee);
            if (earnsInterest && part.on().isAfter(from) && owed.signum() > 0) {
                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
                charged = charged.add(earned);
                unpaidInterest = unpaidInterest.add(earned);
                from = part.on();
            }
            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
            unpaidInterest = unpaidInterest.subtract(toInterest);
            owed = owed.subtract(rest.subtract(toInterest));
        }
        if (earnsInterest && owed.signum() > 0) {
            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
        }
        this.lateFee = fee;
        this.lateInterest = charged;
    }

    /**
     * Works out the late interest each instalment of the plan has been charged by the given day, at the
     * annual rate (a percentage), from the payments (those not reversed count; what credit notes took
     * off counts from the issue date). Payments, in the order they were made, pay each instalment's
     * interest earned so far and then the instalment itself, earliest instalment first. An instalment
     * still not paid off more than {@link #GRACE_DAYS} days after its due date earns interest by the
     * same rule as an invoice: from the end of its own grace week, compounded daily at rate / 365, on
     * what is still unpaid of it, with each payment after its grace week ending a period.
     */
    private void accrueInstalmentInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
            LocalDate today) {
        if (annualRate == null || annualRate.signum() <= 0) {
            return;
        }
        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
        }
        List<Part> inOrder = new ArrayList<>();
        if (getCredited().signum() > 0) {
            inOrder.add(new Part(issueDate == null ? LocalDate.MIN : issueDate, 0L, getCredited()));
        }
        payments.stream().filter(p -> !p.isReversed())
                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
                .filter(p -> !p.on().isAfter(today))
                .forEach(inOrder::add);
        inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
        BigDecimal[] left = inOrder.stream().map(Part::amount).toArray(BigDecimal[]::new);
        BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128));
        List<BigDecimal> charges = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO;
        for (Instalment instalment : schedule(taxRate)) {
            LocalDate due = instalment.dueDate();
            BigDecimal owed = instalment.payment();
            boolean late = false;
            if (due != null && today.isAfter(due.plusDays(GRACE_DAYS))) {
                BigDecimal paidInGrace = BigDecimal.ZERO;
                for (int j = 0; j < left.length; j++) {
                    if (!inOrder.get(j).on().isAfter(due.plusDays(GRACE_DAYS))) {
                        paidInGrace = paidInGrace.add(left[j]);
                    }
                }
                late = paidInGrace.compareTo(owed) < 0;
            }
            BigDecimal charged = BigDecimal.ZERO;
            BigDecimal unpaidInterest = BigDecimal.ZERO;
            LocalDate from = due == null ? null : due.plusDays(GRACE_DAYS);
            for (int j = 0; j < left.length; j++) {
                Part part = inOrder.get(j);
                if (late && part.on().isAfter(from) && owed.signum() > 0) {
                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
                    charged = charged.add(earned);
                    unpaidInterest = unpaidInterest.add(earned);
                    from = part.on();
                }
                BigDecimal toInterest = left[j].min(unpaidInterest).max(BigDecimal.ZERO);
                unpaidInterest = unpaidInterest.subtract(toInterest);
                BigDecimal toOwed = left[j].subtract(toInterest).min(owed).max(BigDecimal.ZERO);
                owed = owed.subtract(toOwed);
                left[j] = left[j].subtract(toInterest).subtract(toOwed);
            }
            if (late && owed.signum() > 0) {
                charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
            }
            charges.add(charged.setScale(scale(), RoundingMode.HALF_UP));
            total = total.add(charged);
        }
        this.instalmentInterest = charges;
        this.lateInterest = total;
    }

    /** The interest the balance earns over the days at the daily growth factor, rounded half up to the cent. */
    private BigDecimal interestOn(BigDecimal balance, BigDecimal daily, long days) {
        if (days <= 0) {
            return zero();
        }
        return balance.multiply(daily.pow((int) days, MathContext.DECIMAL128).subtract(BigDecimal.ONE))
                .setScale(scale(), RoundingMode.HALF_UP);
    }

    /**
     * The early-payment discount on offer at the tax rate: the client's early-payment percentage of the
     * grand total, rounded down to the cent; nothing for a credit note, or an invoice holding back
     * retention or spread over instalments.
     */
    public BigDecimal earlyDiscount(BigDecimal taxRate) {
        if (isCreditNote() || hasPlan() || retentionPct.signum() > 0 || earlyPayDays == null
                || earlyPayPct == null || earlyPayPct.signum() <= 0) {
            return zero();
        }
        return total(taxRate).multiply(earlyPayPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
    }

    /**
     * Whether a sent invoice not yet settled early can still be paid off early on the given day: within
     * the client's early-payment days of its issue date, with an early discount on offer.
     */
    public boolean isEarlyWindowOpen(LocalDate on, BigDecimal taxRate) {
        return status == InvoiceStatus.SENT && issueDate != null && getEarlyDiscountTaken().signum() == 0
                && earlyDiscount(taxRate).signum() > 0 && !on.isAfter(issueDate.plusDays(earlyPayDays));
    }

    /**
     * What would settle the invoice on the given day once the given amount has been paid: what is due
     * less the early discount while the early window is open; null when it is not.
     */
    public BigDecimal settleAmount(BigDecimal paid, BigDecimal taxRate, LocalDate on) {
        BigDecimal due = amountDue(paid, taxRate);
        if (!isEarlyWindowOpen(on, taxRate) || due.signum() <= 0) {
            return null;
        }
        return due.subtract(earlyDiscount(taxRate)).max(zero());
    }

    /** The early discount the invoice was settled with, to the cent; 0 when none was taken. */
    public BigDecimal getEarlyDiscountTaken() {
        return (earlyDiscount == null ? BigDecimal.ZERO : earlyDiscount).setScale(scale(), RoundingMode.HALF_UP);
    }

    /** Settles the invoice with the early discount (0 to clear it again). */
    public void takeEarlyDiscount(BigDecimal amount) {
        this.earlyDiscount = amount;
    }

    /** Whether the invoice is spread over monthly in

package net.officefloor.hq.app.invoices;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.ExchangeRates;
import net.officefloor.hq.app.LateFee;
import net.officefloor.hq.app.LateInterestRate;
import net.officefloor.hq.app.TaxRate;
import net.officefloor.hq.app.Today;
import net.officefloor.hq.app.clients.Client;
import net.officefloor.hq.app.clients.ClientRepository;
import net.officefloor.hq.app.clients.Currency;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Lists a client's invoices, opens one, starts new drafts, duplicates one, adds lines to them, gives them a discount,
 * sends them, voids them and records payments against them.
 */
@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final Today today;
    private final TaxRate taxRate;
    private final Audit audit;
    private final EntityManager entityManager;
    private final ExchangeRates exchangeRates;
    private final LateInterestRate lateInterestRate;
    private final LateFee lateFee;

    public InvoiceService(InvoiceRepository invoices, PaymentRepository payments, ClientRepository clients,
            Today today, TaxRate taxRate, Audit audit, EntityManager entityManager, ExchangeRates exchangeRates,
            LateInterestRate lateInterestRate, LateFee lateFee) {
        this.lateInterestRate = lateInterestRate;
        this.lateFee = lateFee;
        this.exchangeRates = exchangeRates;
        this.entityManager = entityManager;
        this.invoices = invoices;
        this.payments = payments;
        this.clients = clients;
        this.today = today;
        this.taxRate = taxRate;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Invoice> forClient(Long clientId) {
        return loadForClient(clientId);
    }

    /** Every invoice of every client, with its lines. */
    @Transactional(readOnly = true)
    public List<Invoice> all() {
        return withInterest(invoices.findAllByOrderByIdAsc());
    }

    /** The invoice with its lines and the late interest it has been charged; empty if no such invoice. */
    private Optional<Invoice> load(Long id) {
        Optional<Invoice> found = invoices.findWithLinesById(id);
        found.ifPresent(invoice -> withInterest(List.of(invoice)));
        return found;
    }

    /** The client's invoices, lowest id first, with their lines and the late interest they have been charged. */
    private List<Invoice> loadForClient(Long clientId) {
        return withInterest(invoices.findByClientIdOrderByIdAsc(clientId));
    }

    /**
     * Works out the late fee and late interest each of the invoices has been charged by today (see
     * {@link Invoice#accrueLateInterest}).
     */
    private List<Invoice> withInterest(List<Invoice> list) {
        if (list.isEmpty()) {
            return list;
        }
        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
        BigDecimal rate = taxRate.percent();
        BigDecimal annual = lateInterestRate.percent();
        BigDecimal feeUsd = lateFee.usd();
        LocalDate now = today.date();
        list.forEach(i -> i.accrueLateInterest(found, rate, annual, feeUsd, now));
        return list;
    }

    @Transactional(readOnly = true)
    public Optional<Invoice> find(Long id) {
        return load(id);
    }

    /**
     * An empty draft for the client, issued today, due on the client's terms and starting with the
     * client's standard discount; empty if no such client.
     */
    @Transactional
    public Optional<Invoice> newDraft(Long clientId) {
        return clients.findById(clientId).map(client -> {
            LocalDate issued = today.date();
            Invoice draft = Invoice.draft(clientId, client.isTaxExempt(), client.getCurrency(), issued, dueDateFor(clientId, issued));
            draft.setDiscountPct(client.getDiscountPct());
            return invoices.save(draft);
        });
    }

    /**
     * A new draft for the invoice's client with copies of its lines and the same invoice discount,
     * issued today and due as any new invoice is, and records it in the audit; empty if no such
     * invoice. Payments are not copied.
     */
    @Transactional
    public Optional<Invoice> duplicate(Long invoiceId) {
        return load(invoiceId).map(original -> {
            if (original.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note cannot be duplicated.");
            }
            LocalDate issued = today.date();
            Invoice copy = invoices.saveAndFlush(original.duplicate(issued, dueDateFor(original.getClientId(), issued)));
            audit.record("INVOICE_DUPLICATED from=" + InvoiceNumber.of(original.getId())
                    + " to=" + InvoiceNumber.of(copy.getId()));
            return copy;
        });
    }

    /**
     * A new, empty draft credit note against the sent invoice, issued today; empty if no such invoice.
     * A draft, a void invoice or a credit note is refused.
     */
    @Transactional
    public Optional<Invoice> creditNote(Long invoiceId) {
        return load(invoiceId).map(original -> {
            if (original.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note cannot itself be credited.");
            }
            if (original.isDraft()) {
                throw new InvoiceRejectedException("Only a sent invoice can be credited.");
            }
            if (original.isVoid()) {
                throw new InvoiceRejectedException("A void invoice cannot be credited.");
            }
            return invoices.saveAndFlush(original.creditNote(today.date()));
        });
    }

    /**
     * An invoice for a client with payment terms is due that many days after it is issued; otherwise
     * as {@link #dueDateFor(LocalDate)}.
     */
    private LocalDate dueDateFor(Long clientId, LocalDate issued) {
        return clients.findById(clientId)
                .map(Client::getTermsDays)
                .map(days -> issued.plusDays(days))
                .orElseGet(() -> dueDateFor(issued));
    }

    /** A new invoice is due on the last day of the month after the month it is issued in. */
    static LocalDate dueDateFor(LocalDate issued) {
        LocalDate nextMonth = issued.plusMonths(1);
        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
    }

    /**
     * Adds a line to an invoice; empty if no such invoice. The line has already been checked. A sent
     * invoice with no payments goes back to draft; one with a payment refuses it.
     */
    @Transactional
    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            requireWhole(invoice.currency(), unitPrice, "The unit price");
            boolean reopened = reopenForChange(invoice, "A paid invoice cannot take new lines.");
            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate));
            invoices.saveAndFlush(invoice);
            if (reopened) {
                audit.record("INVOICE_REOPENED id=" + invoice.getId());
            }
        });
        return found;
    }

    /**
     * Removes a line from an invoice; empty if no such invoice or line. Refused when what is left would
     * be less than a fixed discount. A sent invoice with no payments goes back to draft; one with a
     * payment refuses it.
     */
    @Transactional
    public Optional<Invoice> removeLine(Long invoiceId, Long lineId) {
        Optional<Invoice> found = load(invoiceId);
        if (found.isEmpty()) {
            return found;
        }
        Invoice invoice = found.get();
        if (!invoice.hasLine(lineId)) {
            return Optional.empty();
        }
        boolean reopened = reopenForChange(invoice, "A paid invoice cannot have lines removed.");
        invoice.removeLine(lineId);
        invoices.saveAndFlush(invoice);
        if (reopened) {
            audit.record("INVOICE_REOPENED id=" + invoice.getId());
        }
        return found;
    }

    /**
     * Changes a line of an invoice; empty if no such invoice or line. The line has already been
     * checked. Refused when the subtotal would be less than a fixed discount. A sent invoice with no
     * payments goes back to draft; one with a payment refuses it.
     */
    @Transactional
    public Optional<Invoice> updateLine(Long invoiceId, Long lineId, String description, BigDecimal qty,
            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
        Optional<Invoice> found = load(invoiceId);
        if (found.isEmpty()) {
            return found;
        }
        Invoice invoice = found.get();
        if (!invoice.hasLine(lineId)) {
            return Optional.empty();
        }
        requireWhole(invoice.currency(), unitPrice, "The unit price");
        boolean reopened = reopenForChange(invoice, "A paid invoice cannot have lines changed.");
        invoice.updateLine(lineId, description, qty, unitPrice, taxExempt, discountPct, taxRate);
        invoices.saveAndFlush(invoice);
        if (reopened) {
            audit.record("INVOICE_REOPENED id=" + invoice.getId());
        }
        return found;
    }

    /**
     * Gives an invoice a percentage discount, or a fixed amount off when one is given; the one given
     * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
     * over the subtotal is refused, as is a discount taking off more than a fifth of the subtotal
     * (after the cap) without a reason. A sent invoice with no payments goes back to draft; one with a
     * payment refuses it.
     */
    @Transactional
    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
            BigDecimal discountCap, String discountReason) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note has no discount.");
            }
            if (discountAmount != null) {
                requireWhole(invoice.currency(), discountAmount, "The discount amount");
            }
            if (discountCap != null) {
                requireWhole(invoice.currency(), discountCap, "The discount cap");
            }
            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
            if (discountAmount != null) {
                invoice.setDiscountAmount(discountAmount);
            } else {
                invoice.setDiscountPct(discountPct);
            }
            invoice.setDiscountCap(discountCap);
            invoice.setDiscountReason(discountReason);
            if (invoice.discountLacksReason()) {
                throw new InvoiceRejectedException(
                        "A discount of more than 20% of the subtotal needs a reason.");
            }
            invoices.saveAndFlush(invoice);
            if (reopened) {
                audit.record("INVOICE_REOPENED id=" + invoice.getId());
            }
        });
        return found;
    }

    /**
     * Sets a draft's due date by hand, kept when it is sent; empty if no such invoice. A date before
     * the issue date or more than {@link Invoice#MAX_DUE_DAYS} days after it is refused, as is any
     * invoice that is not a draft.
     */
    @Transactional
    public Optional<Invoice> setDueDate(Long invoiceId, LocalDate dueDate) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("Only a draft's due date can be set.");
            }
            invoice.setDueDate(dueDate);
            invoices.saveAndFlush(invoice);
        });
        return found;
    }

    /**
     * Sets the percentage of a draft's amount before tax held back as retention; empty if no such invoice.
     * The percentage has already been checked; any invoice that is not a draft, or a credit note, is refused.
     */
    @Transactional
    public Optional<Invoice> setRetention(Long invoiceId, BigDecimal retentionPct) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note holds back no retention.");
            }
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("Retention can only be set on a draft.");
            }
            if (invoice.hasPlan() && retentionPct.signum() > 0) {
                throw new InvoiceRejectedException("An invoice spread over instalments cannot also hold back retention.");
            }
            invoice.setRetentionPct(retentionPct);
            invoices.saveAndFlush(invoice);
        });
        return found;
    }

    /**
     * Spreads a draft over the number of monthly instalments at the annual interest rate; empty if no
     * such invoice. Both have already been checked; any invoice that is not a draft, a credit note, or
     * one holding back retention is refused.
     */
    @Transactional
    public Optional<Invoice> setPlan(Long invoiceId, int instalments, BigDecimal instalmentRate) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isCreditNote()) {
                throw new InvoiceRejectedException("A credit note cannot be spread over instalments.");
            }
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("Only a draft can be spread over instalments.");
            }
            if (invoice.getRetentionPct().signum() > 0) {
                throw new InvoiceRejectedException("An invoice holding back retention cannot also be spread over instalments.");
            }
            invoice.setPlan(instalments, instalmentRate);
            invoices.saveAndFlush(invoice);
        });
        return found;
    }

    /**
     * Releases the retention held back on a sent invoice today, adding it to the amount due (falling
     * due {@link Invoice#RETENTION_DUE_DAYS} days later), and records it in the audit; empty if no such
     * invoice. Refused while anything else is still due, or when there is no retention held to release.
     */
    @Transactional
    public Optional<Invoice> releaseRetention(Long invoiceId) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isDraft() || invoice.isVoid() || invoice.isCreditNote()) {
                throw new InvoiceRejectedException("Retention can only be released on a sent invoice.");
            }
            BigDecimal rate = taxRate.percent();
            BigDecimal held = invoice.retentionHeld(rate);
            if (held.signum() <= 0) {
                throw new InvoiceRejectedException("There is no retention held to release.");
            }
            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), rate);
            if (due.signum() > 0) {
                throw new InvoiceRejectedException("The retention can only be released once nothing else is due; "
                        + invoice.currency().format(due) + " is still due.");
            }
            invoice.releaseRetention(today.date());
            invoices.saveAndFlush(invoice);
            audit.record("RETENTION_RELEASED id=" + invoice.getId() + " amount=" + held.toPlainString());
        });
        return found;
    }

    /**
     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
     * back to draft, to be sent again; an invoice with any payment is refused with the message.
     * Whether it went back to draft.
     */
    private boolean reopenForChange(Invoice invoice, String refusal) {
        if (invoice.isDraft()) {
            return false;
        }
        if (invoice.isVoid()) {
            throw new InvoiceRejectedException("A void invoice cannot be changed.");
        }
        if (invoice.isCreditNote()) {
            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
        }
        if (invoice.hasCreditNotesIssued()) {
            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
        }
        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
            throw new InvoiceRejectedException(refusal);
        }
        invoice.reopen();
        return true;
    }

    /**
     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
     * before today, is refused.
     */
    @Transactional
    public Optional<Invoice> send(Long invoiceId) {
        Optional<Invoice> found = load(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isVoid()) {
                throw new InvoiceRejectedException("A void invoice cannot be sent.");
            }
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("This invoice has already been sent.");
            }
            if (invoice.getLines().isEmpty()) {
                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
            }
            if (invoice.isCreditNote()) {
                String refusal = creditNoteRefusal(invoice);
                if (refusal != null) {
                    throw new InvoiceRejectedException(refusal);
                }
                issue(invoice);
                return;
            }
            if (invoice.discountLacksReason()) {
                throw new InvoiceRejectedException(
                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
            }
            if (invoice.dueDatePassedBy(today.date())) {
                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
                        + ") is already past; set a later due date before sending the invoice.");
            }
            markSent(invoice);
        });
        return found;
    }

    /**
     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
     * hand is already past, stay drafts.
     */
    @Transactional
    public void sendAllDrafts(Long clientId) {
        loadForClient(clientId).stream()
                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
                        && !invoice.dueDatePassedBy(today.date()))
                .forEach(invoice -> {
                    if (!invoice.isCreditNote()) {
                        markSent(invoice);
                    } else if (creditNoteRefusal(invoice) == null) {
                        issue(invoice);
                    }
                });
    }

    /**
     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
     * invoice (not void).
     */
    private String creditNoteRefusal(Invoice note) {
        Invoice original = load(note.getCreditOf()).orElse(null);
        if (original == null || original.isDraft() || original.isVoid()) {
            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
        }
        return null;
    }

    /**
     * Issues the draft credit note today and records it in the audit: its grand total comes off what
     * its original still owes, then the retention it holds back; any rest is held on the client's
     * account as a credit payment dated today, also recorded in the audit.
     */
    private void issue(Invoice note) {
        BigDecimal rate = taxRate.percent();
        Invoice original = load(note.getCreditOf()).orElseThrow();
        // Read again what it has been credited: another credit note may just have been issued against it.
        entityManager.refresh(original);
        withInterest(List.of(original));
        BigDecimal total = note.total(rate);
        BigDecimal[] taken = original.creditTaken(total, paid(List.of(original)).get(original.getId()), rate);
        note.markIssued(today.date(), rate, taken[0], taken[1]);
        invoices.saveAndFlush(note);
        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
                + note.getCreditOf() + " total=" + total.toPlainString());
        BigDecimal rest = total.subtract(taken[0]);
        if (rest.signum() > 0) {
            recordCreditHeld(payments.saveAndFlush(Payment.fromCreditNote(note, rest)));
        }
    }

    /**
     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
     * client's credit on it (see {@link #applyCredit}), unless it is spread over instalments, whose
     * schedule is dated from the new issue date.
     */
    private void markSent(Invoice invoice) {
        LocalDate issued = today.date();
        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
        invoices.saveAndFlush(invoice);
        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
                + " total=" + invoice.total(taxRate.percent()).toPlainString());
        if (!invoice.hasPlan()) {
            applyCredit(invoice);
        }
    }

    /**
     * Uses the client's credit on the invoice just sent, up to what it has due: deposits held for it
     * first, then the oldest payment's credit (lower id first on the same date), never a deposit held
     * for another of the client's drafts; each part applied today and recorded in the audit.
     */
    private void applyCredit(Invoice invoice) {
        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
        LocalDate now = today.date();
        boolean used = false;
        Map<String, Long> drafts = draftsByReference(invoice.getClientId());
        List<Payment> usable = new ArrayList<>();
        List<Payment> others = new ArrayList<>();
        for (Payment payment : payments.findForClient(invoice.getClientId())) {
            Long heldFor = heldFor(payment, drafts);
            if (invoice.getId().equals(heldFor)) {
                usable.add(payment);
            } else if (heldFor == null) {
                others.add(payment);
            }
        }
        usable.addAll(others);
        for (Payment payment : usable) {
            if (due.signum() <= 0) {
                break;
            }
            BigDecimal credit = payment.credit();
            if (credit.signum() <= 0) {
                continue;
            }
            BigDecimal part = credit.min(due);
            payment.apply(invoice.getId(), part, now);
            payments.saveAndFlush(payment);
            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
                    + part.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
            due = due.subtract(part);
            used = true;
        }
        if (used) {
            recordWriteOff(invoice);
        }
    }

    /**
     * Records a deposit of the amount on the date from the client: the whole amount is held on the
     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
     * client. With a reference (null when none, already checked) it is held for that one of the
     * client's drafts (see {@link #heldFor}); a reference that is not one of its drafts' is refused.
     * The amount has already been checked; a date after today is refused.
     */
    @Transactional
    public Optional<Payment> recordDeposit(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
            String reference) {
        Optional<Client> client = clients.findById(clientId);
        if (client.isEmpty()) {
            return Optional.empty();
        }
        if (reference != null && !draftsByReference(clientId).containsKey(reference)) {
            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
                    + " is not the reference of any of this client's drafts, so the deposit cannot be held for it.");
        }
        Currency currency = client.get().getCurrency();
        BigDecimal amount = converted(paidAmount, paidIn, currency);
        LocalDate now = today.date();
        if (date.isAfter(now)) {
            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
        }
        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date, reference)
                .paidIn(paidIn, paidAmount, currency));
        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
                + amount.setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
        return Optional.of(payment);
    }

    /**
     * Refunds the amount of the client's unused credit on the date, never a deposit held for one of its
     * drafts: the oldest payment's credit first
     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
     * such client. The amount has already been checked; a date after today or before a payment it
     * would come from, or an amount more than the client's credit, is refused.
     */
    @Transactional
    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
        Optional<Client> client = clients.findById(clientId);
        if (client.isEmpty()) {
            return Optional.empty();
        }
        Currency currency = client.get().getCurrency();
        requireWhole(currency, amount, "The refund");
        LocalDate now = today.date();
        if (date.isAfter(now)) {
            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
        }
        List<Payment> from = new ArrayList<>();
        List<BigDecimal> parts = new ArrayList<>();
        BigDecimal left = amount;
        BigDecimal credit = BigDecimal.ZERO;
        Map<String, Long> drafts = draftsByReference(clientId);
        for (Payment payment : payments.findForClient(clientId)) {
            if (heldFor(payment, drafts) != null) {
                continue;
            }
            BigDecimal unused = payment.credit();
            if (unused.signum() <= 0) {
                continue;
            }
            credit = credit.add(unused);
            if (left.signum() <= 0) {
                continue;
            }
            BigDecimal part = unused.min(left);
            if (date.isBefore(payment.getDate())) {
                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
                        + payment.getDate() + " it would come from.");
            }
            from.add(payment);
            parts.add(part);
            left = left.subtract(part);
        }
        if (left.signum() > 0) {
            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of "
                    + currency.format(credit) + ".");
        }
        for (int i = 0; i < from.size(); i++) {
            Payment payment = from.get(i);
            payment.refund(parts.get(i));
            payments.saveAndFlush(payment);
            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
                    + parts.get(i).setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
        }
        return Optional.of(clientId);
    }

    /** The unused credit of each client that has any, by client id. */
    @Transactional(readOnly = true)
    public Map<Long, BigDecimal> credits() {
        Map<Long, BigDecimal> credits = new HashMap<>();
        for (Payment payment : payments.findNotReversed()) {
            BigDecimal credit = payment.credit();
            if (credit.signum() > 0) {
                credits.merge(payment.getClientId(), credit, BigDecimal::add);
            }
        }
        return credits;
    }

