  // settle it today while its early-payment window is open (null otherwise).
  earlyDiscount: string;
  settleAmount: string | null;
  // The late interest charged on it so far ("0.00" when none): part of `amountDue`.
  lateInterest: string;
  // The late fee charged on it ("0.00" when none), in its currency: part of `amountDue`.
  lateFee: string;
}


  // Releases the retention held back on a sent invoice, adding it to the amount due; refused (409)
  // while anything else is due or when there is nothing to release.
  releaseRetention(invoiceId: number): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/invoices/${invoiceId}/release-retention`, null);
  }

  // Sends a draft invoice, issuing it today and due on the client's terms, or keeping a due date set
  // by hand; refused (409) when it has no lines or a due date set by hand is before today.
              <tr>
                <th scope="row" colspan="4">Credited</th>
                <td data-testid="invoice-credited">{{ amount(inv.credited) }}</td>
              </tr>
            }
            @if (inv.creditOf === null) {
              <tr>
                <th scope="row" colspan="4">Early-payment discount</th>
                <td data-testid="invoice-early-discount">{{ amount(inv.earlyDiscount) }}</td>
              </tr>
            }
            @if (inv.creditOf === null) {
              <tr>
                <th scope="row" colspan="4">Late fee</th>
                <td data-testid="invoice-late-fee">{{ amount(inv.lateFee) }}</td>
              </tr>
            }
            @if (inv.creditOf === null) {
              <tr>
                <th scope="row" colspan="4">Late interest</th>
                <td data-testid="invoice-interest">{{ amount(inv.lateInterest) }}</td>
              </tr>
            }
            <tr>
              <th scope="row" colspan="4">Amount due</th>
              <td data-testid="invoice-amount-due">{{ amount(inv.amountDue) }}</td>
            </tr>
            @if (inv.settleAmount !== null) {
              <tr>
                <th scope="row" colspan="4">Settles it if paid now (early-payment discount)</th>
                <td data-testid="invoice-settle-amount">{{ amount(inv.settleAmount) }}</td>
              </tr>
            }
            <tr>
              <th scope="row" colspan="4">Written off (worth under $1.00 left)</th>
              <td data-testid="invoice-written-off">{{ amount(inv.writtenOff) }}</td>

        @if (
          inv.creditOf === null &&
          inv.status !== 'DRAFT' &&
          inv.status !== 'VOID' &&
          +inv.retentionHeld > 0
        ) {
          <button
            type="button"
            data-testid="invoice-release-retention"
            [disabled]="releasing()"
            (click)="releaseRetention(inv.id)"
          >
            Release retention
          </button>
        }
        @if (releaseError()) {
          <p role="alert" data-testid="invoice-release-error">{{ releaseError() }}</p>
        }

        @if (inv.status === 'DRAFT') {
          <button type="button" data-testid="invoice-send" [disabled]="sending()" (click)="send(inv)">
            {{ inv.creditOf === null ? 'Send invoice' : 'Issue credit note' }}
          </button>
          @if (sendError()) {
            <p role="alert" data-testid="invoice-send-error">{{ sendError() }}</p>
          }
        }


